"""Writes the Go SDK's generated files: go/types_gen.go and go/operations_gen.go."""

from __future__ import annotations

import re
import subprocess

from .model import ROOT, Model, OperationModel, Ref, load

OUT = ROOT / "go"
HEADER = "// Code generated by codegen (python -m codegen go) from the repo's schema/, operations/ and behavior.json. DO NOT EDIT.\n\n"

SCALARS = {
    "ID": "string",
    "String": "string",
    "Int": "int",
    "Float": "float64",
    "Boolean": "bool",
    "DateTime": "time.Time",
    "Decimal": "string",
    "JSON": "json.RawMessage",
}
# Types that are already nil-able, so nullable ones aren't pointers.
NILABLE = {"json.RawMessage"}
INITIALISMS = {"id": "ID", "ids": "IDs", "url": "URL", "urls": "URLs", "api": "API", "po": "PO"}


def go_name(name: str) -> str:
    """externalIds → ExternalIDs, siteId → SiteID, poNumber → PONumber."""
    words = re.findall(r"[a-z0-9]+|[A-Z][a-z0-9]*", name)
    return "".join(INITIALISMS.get(w.lower(), w[0].upper() + w[1:]) for w in words)


def go_param(name: str) -> str:
    """webhookId → webhookID: a Go-style parameter name."""
    exported = go_name(name)
    for initialism in sorted(INITIALISMS.values(), key=len, reverse=True):
        if exported.startswith(initialism):
            return initialism.lower() + exported[len(initialism) :]
    return exported[0].lower() + exported[1:]


def enum_const(enum: str, value: str) -> str:
    return enum + "".join(part.capitalize() for part in value.lower().split("_"))


def go_type(ref: Ref, *, pointer_if_nullable: bool = True) -> str:
    if ref.kind == "list":
        assert ref.of
        return "[]" + go_type(ref.of)
    inner = SCALARS[ref.name] if ref.kind == "scalar" else ref.name
    if ref.nullable and pointer_if_nullable and inner not in NILABLE:
        return "*" + inner
    return inner


def comment(text: str | None, indent: str = "") -> str:
    if not text:
        return ""
    return "".join(f"{indent}// {line}".rstrip() + "\n" for line in text.splitlines())


def emit_types(model: Model) -> str:
    out = [HEADER, "package rockware\n\nimport (\n\t\"encoding/json\"\n\t\"time\"\n)\n\n"]
    out.append("var _ = json.RawMessage(nil)\nvar _ = time.Time{}\n\n")
    for enum in model.enums:
        out.append(comment(enum.description))
        out.append(f"type {enum.name} string\n\nconst (\n")
        for value in enum.values:
            out.append(f'\t{enum_const(enum.name, value)} {enum.name} = "{value}"\n')
        out.append(")\n\n")
    for input_class in model.inputs:
        out.append(comment(input_class.description) or f"// {input_class.name} is sent to the API.\n")
        out.append(f"type {input_class.name} struct {{\n")
        for f in input_class.fields:
            out.append(comment(f.description, "\t"))
            if f.ref.nullable:
                # Left out when nil, so a field you don't set is left as it is.
                out.append(f'\t{go_name(f.name)} {go_type(f.ref)} `json:"{f.name},omitempty"`\n')
            else:
                out.append(f'\t{go_name(f.name)} {go_type(f.ref)} `json:"{f.name}"`\n')
        out.append("}\n\n")
    for object_class in model.classes:
        out.append(f"type {object_class.name} struct {{\n")
        if object_class.base:
            out.append(f"\t{object_class.base}\n")
        for f in object_class.fields:
            out.append(comment(f.description, "\t"))
            out.append(f'\t{go_name(f.name)} {go_type(f.ref)} `json:"{f.name}"`\n')
        out.append("}\n\n")
    return "".join(out)


def result_type(op: OperationModel) -> tuple[str, str]:
    """The method's result type, and the zero value to return with an error."""
    ref = op.result
    if ref.kind == "object":
        return ("*" + ref.name, "nil") if ref.nullable else (ref.name, ref.name + "{}")
    if ref.kind == "list":
        return go_type(ref), "nil"
    typ = go_type(ref)
    zero = {"bool": "false", "int": "0", "float64": "0", "string": '""'}.get(typ, "nil")
    return typ, zero


def emit_operations(model: Model) -> str:
    out = [HEADER, 'package rockware\n\nimport (\n\t"context"\n\t"iter"\n\t"time"\n)\n\n']
    out.append("var _ = time.Time{}\n\n")
    out.append("// operations is every operation in operations/, by name.\nvar operations = map[string]*operation{\n")
    for op in model.operations:
        out.append(
            f'\t"{op.name}": {{name: "{op.name}", root: "{op.root}", mutation: {str(op.mutation).lower()}, '
            f"safeToRepeat: {str(op.safe_to_repeat).lower()}, document: {go_string(op.document)}}},\n"
        )
    out.append("}\n\n")
    out.append(f"const retryAttempts = {model.retry['attempts']}\n")
    out.append(f"const retryBaseDelay = {model.retry['baseDelayMs']} * time.Millisecond\n")
    out.append(f"const retryMaxJitter = {model.retry['maxJitterMs']} * time.Millisecond\n")
    out.append(f"const maxRetryAfter = {model.retry['maxRetryAfterSeconds']} * time.Second\n")
    out.append(f'\n// Version is this SDK\'s version.\nconst Version = "{model.version}"\n\n')

    for op in model.operations:
        required = [v for v in op.variables if not v.ref.nullable]
        optional = [v for v in op.variables if v.ref.nullable]
        typ, zero = result_type(op)

        if optional:
            out.append(f"// {op.name}Options holds {op.name}'s optional arguments. Nil ones aren't sent.\n")
            out.append(f"type {op.name}Options struct {{\n")
            for v in optional:
                out.append(f"\t{go_name(v.name)} {go_type(v.ref)}\n")
            out.append("}\n\n")

        params = ["ctx context.Context"] + [f"{go_param(v.name)} {go_type(v.ref)}" for v in required]
        if optional:
            params.append(f"opts *{op.name}Options")
        method_doc = op.description or f"{op.name} sends the {op.name} operation."
        out.append(comment(f"{op.name}: {method_doc}"))
        out.append(f"func (c *Client) {op.name}({', '.join(params)}) ({typ}, error) {{\n")
        out.append(variables_code(required, optional))
        out.append(f"\tvar out {typ}\n")
        out.append(f'\tif err := c.run(ctx, operations["{op.name}"], vars, &out); err != nil {{\n')
        out.append(f"\t\treturn {zero}, err\n\t}}\n\treturn out, nil\n}}\n\n")

        if op.page_node:
            page_optional = [v for v in optional if v.name != "after"]
            node = go_type(op.page_node)
            all_name = "ListAll" + op.name.removeprefix("List")
            out.append(f"// {all_name}Options holds {all_name}'s optional arguments. Nil ones aren't sent.\n")
            out.append(f"type {all_name}Options struct {{\n")
            for v in page_optional:
                out.append(f"\t{go_name(v.name)} {go_type(v.ref)}\n")
            out.append("\t// MaxPages stops after this many pages. 0 means 10,000.\n\tMaxPages int\n}\n\n")
            params = ["ctx context.Context"] + [f"{go_param(v.name)} {go_type(v.ref)}" for v in required]
            params.append(f"opts *{all_name}Options")
            out.append(f"// {all_name} gives every record from {op.name}, page by page. See SPEC.md, Paging.\n")
            out.append(f"func (c *Client) {all_name}({', '.join(params)}) iter.Seq2[{node}, error] {{\n")
            out.append(variables_code(required, page_optional))
            out.append("\tmaxPages := 0\n\tif opts != nil {\n\t\tmaxPages = opts.MaxPages\n\t}\n")
            out.append(f'\treturn listAll[{node}](ctx, c, operations["{op.name}"], vars, maxPages)\n}}\n\n')
    return "".join(out)


def variables_code(required, optional) -> str:
    lines = ["\tvars := map[string]any{"]
    lines.append(", ".join(f'"{v.name}": {go_param(v.name)}' for v in required))
    lines.append("}\n")
    code = "".join(lines)
    if optional:
        code += "\tif opts != nil {\n"
        for v in optional:
            code += f"\t\tif opts.{go_name(v.name)} != nil {{\n\t\t\tvars[\"{v.name}\"] = opts.{go_name(v.name)}\n\t\t}}\n"
        code += "\t}\n"
    return code


def emit_dispatch(model: Model) -> str:
    """A table for the conformance tests: each operation's real method, called
    with arguments read from JSON."""
    out = [HEADER, 'package rockware\n\nimport (\n\t"context"\n\t"encoding/json"\n)\n\n']
    out.append("type callFunc func(ctx context.Context, c *Client, raw map[string]json.RawMessage) (any, error)\n")
    out.append("type pageFunc func(ctx context.Context, c *Client, raw map[string]json.RawMessage, maxPages int, each func(any)) error\n\n")
    out.append("var calls = map[string]callFunc{\n")
    for op in model.operations:
        required = [v for v in op.variables if not v.ref.nullable]
        optional = [v for v in op.variables if v.ref.nullable]
        out.append(f'\t"{op.name}": func(ctx context.Context, c *Client, raw map[string]json.RawMessage) (any, error) {{\n')
        out.append(decode_code(op.name + "Options", required, optional))
        args = ["ctx"] + [go_param(v.name) for v in required] + (["opts"] if optional else [])
        out.append(f"\t\treturn c.{op.name}({', '.join(args)})\n\t}},\n")
    out.append("}\n\nvar pages = map[string]pageFunc{\n")
    for op in model.operations:
        if not op.page_node:
            continue
        required = [v for v in op.variables if not v.ref.nullable]
        optional = [v for v in op.variables if v.ref.nullable and v.name != "after"]
        all_name = "ListAll" + op.name.removeprefix("List")
        out.append(
            f'\t"{op.name}": func(ctx context.Context, c *Client, raw map[string]json.RawMessage, maxPages int, each func(any)) error {{\n'
        )
        out.append(decode_code(all_name + "Options", required, optional, error_only=True))
        out.append("\t\topts.MaxPages = maxPages\n" if optional else f"\t\topts := &{all_name}Options{{MaxPages: maxPages}}\n")
        args = ["ctx"] + [go_param(v.name) for v in required] + ["opts"]
        out.append(f"\t\tfor record, err := range c.{all_name}({', '.join(args)}) {{\n")
        out.append("\t\t\tif err != nil {\n\t\t\t\treturn err\n\t\t\t}\n\t\t\teach(record)\n\t\t}\n\t\treturn nil\n\t},\n")
    out.append("}\n")
    return "".join(out)


def decode_code(options: str, required, optional, error_only: bool = False) -> str:
    fail = "return err" if error_only else "return nil, err"
    code = ""
    for v in required:
        code += f"\t\tvar {go_param(v.name)} {go_type(v.ref)}\n"
        code += f'\t\tif err := json.Unmarshal(raw["{v.name}"], &{go_param(v.name)}); err != nil {{\n\t\t\t{fail}\n\t\t}}\n'
    if optional:
        code += f"\t\topts := &{options}{{}}\n"
        for v in optional:
            code += (
                f'\t\tif value, ok := raw["{v.name}"]; ok {{\n'
                f"\t\t\tif err := json.Unmarshal(value, &opts.{go_name(v.name)}); err != nil {{\n\t\t\t\t{fail}\n\t\t\t}}\n\t\t}}\n"
            )
    return code


def go_string(text: str) -> str:
    if "`" not in text:
        return "`" + text + "`"
    return '"' + text.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n") + '"'


def main() -> None:
    model = load()
    (OUT / "types_gen.go").write_text(emit_types(model))
    (OUT / "operations_gen.go").write_text(emit_operations(model))
    (OUT / "dispatch_gen_test.go").write_text(emit_dispatch(model))
    for name in ("types_gen.go", "operations_gen.go", "dispatch_gen_test.go"):
        formatted = subprocess.run(["gofmt", "-l", "-w", str(OUT / name)], capture_output=True, text=True)
        if formatted.returncode != 0:
            raise SystemExit(f"gofmt failed on {name}:\n{formatted.stderr}")
    print(f"Made {len(model.operations)} operations for the Go SDK {model.version}.")
